"use strict";
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[[6,0,2],[2,4,6],[4,6,0],[0,2,4],[6,2,4],[2,0,6]];
let variant=OrionProgress.variant('dawn'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,length=1,solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){return journeys[v][s];}
const phases=[['Noon','正午'],['Afternoon','下午'],['Sunset','日落'],['Evening','晚上'],['Midnight','午夜'],['Before dawn','黎明前'],['Sunrise','日出'],['Morning','上午']];
function phase(n){return t(...phases[n]);}
function setLength(n){if(solved||!Number.isInteger(n)||n<0||n>7)return;length=n;state='ready';render();}
function resetTrial(){length=1;solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('dawn')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;if(length!==challenge())state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('daybreak');}render();if(solved&&stage<2)$('next').focus();}
function drawing(){const a=length*Math.PI/4,x=150+85*Math.cos(a),y=135-85*Math.sin(a);return `<svg viewBox="0 0 380 280" role="img" aria-label="${t(`North-pole view. Sun on the right. Observer at step ${length}: ${phase(length)}. Earth rotates anticlockwise.`,`北極上方視角。太陽在右邊。觀察者在第 ${length} 格：${phase(length)}。地球逆時針自轉。`)}"><defs><clipPath id="earthclip"><circle cx="150" cy="135" r="85"/></clipPath></defs><circle cx="150" cy="135" r="85" fill="#16344a" stroke="#97c6d0" stroke-width="2"/><path d="M150 50A85 85 0 0 1 150 220Z" fill="#8cc9c4"/><g clip-path="url(#earthclip)" transform="rotate(${-length*45} 150 135)" stroke="#a5c5bf" stroke-width="1" opacity=".6"><ellipse cx="150" cy="135" rx="85" ry="32" fill="none"/><ellipse cx="150" cy="135" rx="32" ry="85" fill="none"/><path d="M65 135H235M150 50V220"/></g><circle cx="330" cy="135" r="28" fill="#ffd978"/><g stroke="#f7d68a" stroke-width="2">${[100,135,170].map(v=>`<path d="M292 ${v}H251m7 -5l-7 5 7 5"/>`).join('')}</g><text x="330" y="183" text-anchor="middle" fill="#ffe4a6" font-size="15">${t('Sun','太陽')}</text><path d="M256 127A106 106 0 0 0 178 32m9 -3l-9 3 5 9" fill="none" stroke="#efd08b" stroke-width="3"/><circle cx="${x}" cy="${y}" r="10" fill="#ffdf82" stroke="#382812" stroke-width="3"/><text x="${x}" y="${y+4}" text-anchor="middle" fill="#172d36" font-size="12">◆</text><text x="150" y="253" text-anchor="middle" fill="#f2e4c3" font-size="15">${t('◆ Observer on the equator','◆ 赤道上的觀察者')}</text><text x="150" y="20" text-anchor="middle" fill="#f2e4c3" font-size="13">${t('View from above the North Pole','從北極上方俯視')}</text></svg>`;}
function hints(){const q=challenge();return[t('Move the marker around Earth. Which half faces the Sun?','把標記移到地球不同位置。哪一半面向太陽？'),t('Earth turns anticlockwise in this view. Sunrise enters the bright half; sunset enters the dark half.','在這個視角，地球逆時針自轉。日出時進入亮的一半，日落時進入暗的一半。'),t(`Try step ${q} for ${phase(q)}. Follow the gold rotation arrow to understand what happens next.`,`試試第 ${q} 格的${phase(q)}。跟隨金色自轉箭嘴，想想接下來會怎樣。`)];}
function render(){const q=challenge(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Dawn Observatory · Orion','黎明天文臺 · Orion');$('stageTitle').textContent=t(`Observation ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 次觀察 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Dawn seals · ${p} / 3`,`黎明封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('diagram').innerHTML=drawing();$('length').value=length;$('length').disabled=solved;$('turn').disabled=solved;$('lengthValue').textContent=String(length);$('length').setAttribute('aria-valuetext',t(`Step ${length}: ${phase(length)}`,`第 ${length} 格：${phase(length)}`));
$('goal').textContent=t(`Turn Earth until the observer experiences ${phase(q).toLowerCase()}.`,`轉動地球，讓觀察者經歷${phase(q)}。`);$('reading').textContent=t(`At the observer: ${phase(length)}.`,`觀察者所在地：${phase(length)}。`);$('reference').textContent=length===2?t('The observer is leaving sunlight.','觀察者正在離開陽光。'):length===6?t('The observer is entering sunlight.','觀察者正在進入陽光。'):[0,1,7].includes(length)?t('This place faces the Sun and receives daylight.','這個位置面向太陽，受到陽光照射。'):t('This place faces away from the Sun.','這個位置背向太陽。');const messages={ready:['Explore the eight positions, then check your observation.','探索八個位置，再檢查你的觀察。'],wrong:['That is a different part of the day. Follow the observer and try again.','這是一天中的另一個時段。觀察標記，再試一次。'],success:['The observation matches! Another observatory seal opens.','觀察正確！又一道天文臺封印打開了。']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;
$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('daybreak')?t('Daybreak Sigil saved in your collection.','破曉符印已存入收藏。'):'';}
$('length').oninput=e=>setLength(Number(e.target.value));$('turn').onclick=()=>setLength((length+1)%8);
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('dawn',variant);observedVariant=OrionProgress.variant('dawn');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('daybreak');render();};function syncProgress(){const v=OrionProgress.variant('dawn'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('daybreak')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
